import type { EmittedCard } from "./cardTool";

/**
 * The emit_card boundary lint (contract v1, spec section 4.1): G-1 the CI
 * gate and G-3 the card/voice lint. Each rule turns a prompt rule into a
 * host refusal with corrective text - simultaneously a safety bound and a
 * training signal. A refused card is never shown; the thrown message reaches
 * the model as a loud tool error and it revises.
 *
 * Applies to the FIRSTMATE persona's emit_card only; crewmate cards keep
 * their prompt-steered contract. Pattern seeds are captain-annotatable.
 */

/** How long a green check_pr_ci result stays fresh for the G-1 land gate. */
export const CI_FRESHNESS_MS = 5 * 60_000;

/** Action ids that make a decision card a land/merge offer (G-1). */
const LAND_ACTION_IDS = new Set(["land", "merge", "merge-pr"]);

/** The host-owned settle ids that actually perform a merge in act(). */
const MERGE_ACTION_IDS = new Set(["merge-pr", "land"]);

/**
 * A settle-shaped action id that is not exactly reserved. act() dispatches
 * on the literal id, so "merge-pr55" or "land-it" silently degrades to a
 * steer round-trip and no merge ever runs; the model must be refused rather
 * than left to invent per-PR ids.
 */
const SETTLE_LOOKALIKE = /^(merge[-_ ]?pr|merge|land)([-_ ][a-z0-9]+|\d+)?$/i;

/** The reserved settle ids a lookalike could have meant. */
const RESERVED_SETTLE_IDS = new Set(["merge-pr", "land"]);

/**
 * The first settle-shaped action id that the host would not dispatch, if
 * any. Shared with the crewmate card boundary: both personas render the
 * same footer, and a near-miss id no-ops identically on either.
 */
export function freeformSettleActionId(actions: { id: string }[]): string | undefined {
  return actions.find(
    (action) => SETTLE_LOOKALIKE.test(action.id) && !RESERVED_SETTLE_IDS.has(action.id),
  )?.id;
}

/** The refusal text for a near-miss settle id, shared by both boundaries. */
export function freeformSettleRefusal(actionId: string): string {
  return `action id "${actionId}" is freeform and has no host semantics; use the exact reserved id "merge-pr" to merge a GitHub PR or "land" to merge into the local checkout - any other id is only a steer and merges nothing.`;
}

/** L1 seed list: progress/status card patterns (case-insensitive). */
const PROGRESS_PATTERNS: RegExp[] = [
  /still (pending|running|waiting)/i,
  /watching (the )?(run|ci|checks)/i,
  /no red yet/i,
  /ci is (pending|running)/i,
  /in progress/i,
  /working on it/i,
  /will (report|update)/i,
];

/** L3: a title led by a bare SHA, or that is only "PR <n>". */
const SHA_LEAD = /^[0-9a-f]{7,40}\b/i;
const BARE_PR_TITLE = /^PR\s+#?\d+$/i;

/** L4: emoji (extended pictographics) in decision/note copy. */
const EMOJI = /\p{Extended_Pictographic}/u;

export type CardLintContext = {
  /** The delivery posture of the task a card names, when known. */
  taskDelivery: (taskId: string) => "direct-pr" | "local-only" | undefined;
  /** Whether a green check_pr_ci result at most CI_FRESHNESS_MS old exists. */
  freshGreenCi: (taskId: string) => boolean;
  /** The last known CI state for refusal copy ("red", "never checked", ...). */
  ciStateText: (taskId: string) => string;
  /** Open parked decisions' card ids (the L6 re-ask gate). */
  parkedDecisionIds: () => Set<string>;
  /** Resolve a model-passed stable id to the routable card id. */
  resolveCardId: (stableId: string) => string;
  /**
   * Whether a task id names a record (task-system P1, attach first). Absent
   * = the boundary has no task record to check against.
   */
  taskExists?: (taskId: string) => boolean;
};

/** The P1 attach-first refusal for a note that names no task and asserts nothing. */
export const NOTE_NEEDS_TASK_REFUSAL =
  "every card is about a task: pass task_id when this answers a question about existing work (the about line, the tasks index, or crew_status name it), or standalone true only when the ask is a one-off with no connection or consequence to any work.";

/**
 * Lint one Firstmate card. Returns the corrective refusal text, or
 * undefined when the card passes. Order: the re-ask gate and the CI gate
 * first (they are the decision-integrity rules), then the voice slice.
 */
export function lintFirstmateCard(card: EmittedCard, context: CardLintContext): string | undefined {
  // Attach first (task-system P1, D1): a task_id must name a record; a note
  // must either name its task or assert it is standalone - never neither,
  // and not both.
  if (card.taskId && context.taskExists && !context.taskExists(card.taskId)) {
    return `unknown task_id "${card.taskId}"; use a task id from the about line, the tasks index, or crew_status.`;
  }
  if (card.taskId && card.standalone) {
    return "pass either task_id (the card is about that task) or standalone true (it is about no task), not both.";
  }
  if (
    (card.kind === "note" || card.kind === "live-prototype") &&
    !card.taskId &&
    !card.standalone
  ) {
    return NOTE_NEEDS_TASK_REFUSAL;
  }

  // L6: the parked-decision re-ask refusal, exact-id keyed.
  if (card.kind === "decision" && card.id) {
    const resolved = context.resolveCardId(card.id);
    if (context.parkedDecisionIds().has(resolved)) {
      return "that decision is parked and returns on its own; recall_decision brings it back now.";
    }
  }

  // A settle offer is dispatched by the host on the literal action id and
  // the card's task_id. Both checks run before the taskId-scoped rules
  // below, because a card that omits task_id would otherwise skip every
  // gate at once and still render a button that cannot merge anything.
  if (card.kind === "decision") {
    const lookalike = freeformSettleActionId(card.actions);
    if (lookalike) return freeformSettleRefusal(lookalike);
    const settle = card.actions.find((action) => MERGE_ACTION_IDS.has(action.id));
    if (settle && !card.taskId) {
      return `a decision offering "${settle.id}" must pass task_id; without it the host cannot tell which task to settle and the button does nothing.`;
    }
  }

  if (card.kind === "decision" && card.taskId) {
    const delivery = context.taskDelivery(card.taskId);
    const actionIds = new Set(card.actions.map((action) => action.id));
    if (delivery === "direct-pr" && actionIds.has("land")) {
      return 'a direct-PR decision must use "merge-pr"; "land" means merge into the local checkout.';
    }
    if (delivery !== "direct-pr" && actionIds.has("merge-pr")) {
      return '"merge-pr" is only valid for a direct-PR task.';
    }
  }

  // G-1: a decision offering land/merge on a direct-pr task needs a fresh
  // green check_pr_ci result recorded by the host.
  if (
    card.kind === "decision" &&
    card.taskId &&
    card.actions.some((action) => LAND_ACTION_IDS.has(action.id)) &&
    context.taskDelivery(card.taskId) === "direct-pr" &&
    !context.freshGreenCi(card.taskId)
  ) {
    return `CI for task ${card.taskId} is ${context.ciStateText(card.taskId)} - steer the crewmate or re-check; a merge decision needs fresh green CI.`;
  }

  const copyLinted = card.kind === "decision" || card.kind === "note";

  // L1: progress/status cards belong in the feed, never on the stack.
  const progressHaystack = copyLinted ? `${card.title}\n${card.body}` : card.title;
  const progress = PROGRESS_PATTERNS.find((pattern) => pattern.test(progressHaystack));
  if (progress) {
    return `this reads as a progress or status card ("${progress.source}"); progress belongs in the feed or in silence, never on a card.`;
  }

  // L2: a PR decision must carry its link.
  if (
    card.kind === "decision" &&
    card.taskId &&
    context.taskDelivery(card.taskId) === "direct-pr" &&
    !/https:\/\//.test(card.body)
  ) {
    return "a decision about a direct-pr task must include the PR's https URL in its body.";
  }

  // L3: the title leads with the work, never a bare SHA or PR number.
  if (SHA_LEAD.test(card.title.trim()) || BARE_PR_TITLE.test(card.title.trim())) {
    return "the title must name the work in plain language, not lead with a SHA or be only a PR number.";
  }

  if (copyLinted) {
    // L4: voice mechanics.
    if (card.title.includes("!") || card.body.includes("!")) {
      return "card copy is calm and factual: no exclamation points.";
    }
    if (EMOJI.test(card.title) || EMOJI.test(card.body)) {
      return "card copy is calm and factual: no emoji.";
    }
  }

  return undefined;
}

import { describe, expect, it } from "vitest";
import { type CardLintContext, lintFirstmateCard } from "./cardLint";
import { type EmittedCard, resolveFirstmateCardId } from "./cardTool";

/**
 * The v1 emit_card boundary lint (G-1 + G-3): every refusal is corrective
 * text; a passing card returns undefined. These rules are the mechanical
 * slice of card discipline - the trained model carries the rest.
 */

function context(overrides: Partial<CardLintContext> = {}): CardLintContext {
  return {
    taskDelivery: () => undefined,
    freshGreenCi: () => false,
    ciStateText: () => "unknown - check_pr_ci has not been called for it",
    parkedDecisionIds: () => new Set<string>(),
    resolveCardId: resolveFirstmateCardId,
    ...overrides,
  };
}

function note(overrides: Partial<EmittedCard> = {}): EmittedCard {
  return {
    kind: "note",
    title: "Quota headroom",
    body: "Codex has 62% of the weekly window left.",
    actions: [],
    // Attach first (task-system P1): a card names its task or, as a note,
    // asserts it is a one-off; the rules below are tested on a standalone
    // note unless the case names a task.
    ...(overrides.taskId ? {} : { standalone: true }),
    ...overrides,
  };
}

describe("lintFirstmateCard", () => {
  it("attach first: a note must name its task or assert standalone, never neither or both", () => {
    expect(lintFirstmateCard(note({ standalone: undefined }), context())).toMatch(
      /task_id.*standalone/,
    );
    expect(
      lintFirstmateCard(
        note({ standalone: undefined, taskId: "ab12cd34" }),
        context({ taskExists: (id) => id === "ab12cd34" }),
      ),
    ).toBeUndefined();
    expect(lintFirstmateCard(note({ standalone: true, taskId: "ab12cd34" }), context())).toMatch(
      /not both/,
    );
    const prototype: EmittedCard = {
      kind: "live-prototype",
      title: "Course preview",
      body: "<button data-fm-action='hold'>Hold</button>",
      actions: [{ id: "hold", label: "Hold" }],
    };
    expect(lintFirstmateCard(prototype, context())).toMatch(/task_id.*standalone/);
    expect(lintFirstmateCard({ ...prototype, standalone: true }, context())).toBeUndefined();
  });

  it("attach first: a task_id must name a record when the boundary can check", () => {
    const card = note({ standalone: undefined, taskId: "nope" });
    expect(lintFirstmateCard(card, context({ taskExists: () => false }))).toMatch(
      /unknown task_id "nope"/,
    );
    // No record to check against (a boundary without a task store) trusts the id.
    expect(lintFirstmateCard(card, context())).toBeUndefined();
  });

  it("attach first: a decision needs no assertion - a task-less one files its own task", () => {
    const decision: EmittedCard = {
      kind: "decision",
      title: "Which project?",
      body: "Two repositories plausibly match.",
      actions: [
        { id: "a", label: "A" },
        { id: "b", label: "B" },
      ],
    };
    expect(lintFirstmateCard(decision, context())).toBeUndefined();
  });

  it("passes a calm factual note", () => {
    expect(lintFirstmateCard(note(), context())).toBeUndefined();
  });

  it("L1: refuses progress and status cards toward the feed", () => {
    for (const title of [
      "Still waiting on CI",
      "Watching the run",
      "No red yet",
      "CI is pending",
      "Refactor in progress",
      "Working on it",
      "Will report when done",
    ]) {
      const refusal = lintFirstmateCard(note({ title }), context());
      expect(refusal, title).toMatch(/progress|feed/);
    }
    const bodyRefusal = lintFirstmateCard(
      note({ title: "Auth refactor", body: "The work is still running; no red yet." }),
      context(),
    );
    expect(bodyRefusal).toMatch(/feed/);
  });

  it("G-1: refuses a PR merge decision without fresh green CI", () => {
    const card = note({
      kind: "decision",
      title: "Merge the auth refactor",
      body: "firstmate-3000 PR 23 is ready. https://github.com/x/y/pull/23",
      actions: [{ id: "merge-pr", label: "Merge PR" }],
      taskId: "ab12cd34",
    });
    const ctx = context({
      taskDelivery: () => "direct-pr",
      freshGreenCi: () => false,
      ciStateText: () => "pending",
    });
    expect(lintFirstmateCard(card, ctx)).toBe(
      "CI for task ab12cd34 is pending - steer the crewmate or re-check; a merge decision needs fresh green CI.",
    );
    expect(
      lintFirstmateCard(
        card,
        context({ taskDelivery: () => "direct-pr", freshGreenCi: () => true }),
      ),
    ).toBeUndefined();
    expect(
      lintFirstmateCard(
        { ...card, actions: [{ id: "keep-open", label: "Keep it open" }] },
        context({ taskDelivery: () => "direct-pr" }),
      ),
    ).toBeUndefined();
  });

  it("keeps local landing and GitHub PR merge semantics distinct", () => {
    const base = note({
      kind: "decision",
      title: "Finish the auth refactor",
      body: "Ready. https://github.com/x/y/pull/23",
      taskId: "ab12cd34",
    });
    expect(
      lintFirstmateCard(
        { ...base, actions: [{ id: "land", label: "Merge PR" }] },
        context({ taskDelivery: () => "direct-pr", freshGreenCi: () => true }),
      ),
    ).toMatch(/merge-pr.*land/);
    expect(
      lintFirstmateCard(
        { ...base, actions: [{ id: "merge", label: "Merge PR" }] },
        context({ taskDelivery: () => "direct-pr", freshGreenCi: () => true }),
      ),
    ).toMatch(/freeform.*no host semantics/);
    expect(
      lintFirstmateCard(
        { ...base, actions: [{ id: "merge-pr", label: "Merge PR" }] },
        context({ taskDelivery: () => "local-only", freshGreenCi: () => true }),
      ),
    ).toMatch(/only valid for a direct-PR task/);
  });

  it("refuses a near-miss settle id that the host would never dispatch", () => {
    // The live regression: every Merge PR card ever emitted used a per-PR
    // id like "merge-pr55" and no task_id, so act() fell through to the
    // steer branch and no PR was ever merged.
    const base = note({
      kind: "decision",
      title: "Finish the auth refactor",
      body: "Ready. https://github.com/x/y/pull/55",
      taskId: "ab12cd34",
    });
    for (const id of ["merge-pr55", "merge_pr", "mergepr55", "land-it", "land2"]) {
      const refusal = lintFirstmateCard(
        { ...base, actions: [{ id, label: "Merge PR 55" }] },
        context({ taskDelivery: () => "direct-pr", freshGreenCi: () => true }),
      );
      expect(refusal, id).toMatch(/freeform.*no host semantics/);
    }
    // Reserved ids and unrelated freeform ids are untouched.
    expect(
      lintFirstmateCard(
        {
          ...base,
          actions: [
            { id: "merge-pr", label: "Merge PR" },
            { id: "leave-pr55", label: "Leave it open" },
            { id: "keep-waiting", label: "Keep waiting" },
          ],
        },
        context({ taskDelivery: () => "direct-pr", freshGreenCi: () => true }),
      ),
    ).toBeUndefined();
  });

  it("refuses a merge or land offer that omits task_id", () => {
    // Without task_id every taskId-scoped gate below silently skips and
    // act() cannot resolve a task, so the button does nothing.
    for (const id of ["merge-pr", "land"]) {
      const refusal = lintFirstmateCard(
        note({
          kind: "decision",
          title: "Finish the auth refactor",
          body: "Ready. https://github.com/x/y/pull/55",
          actions: [{ id, label: "Merge PR" }],
        }),
        context({ taskDelivery: () => "direct-pr", freshGreenCi: () => true }),
      );
      expect(refusal, id).toMatch(/must pass task_id/);
    }
  });

  it("L2: a direct-pr decision must carry its https link", () => {
    const card = note({
      kind: "decision",
      title: "Merge the auth refactor",
      body: "firstmate-3000 PR 23 is green.",
      actions: [{ id: "merge-pr", label: "Merge PR" }],
      taskId: "ab12cd34",
    });
    const ctx = context({ taskDelivery: () => "direct-pr", freshGreenCi: () => true });
    expect(lintFirstmateCard(card, ctx)).toMatch(/https URL/);
  });

  it("L3: refuses SHA-led and bare-PR titles", () => {
    expect(lintFirstmateCard(note({ title: "b45f6627 is green" }), context())).toMatch(
      /plain language/,
    );
    expect(lintFirstmateCard(note({ title: "PR 23" }), context())).toMatch(/plain language/);
    // A title that merely mentions a PR among words is fine.
    expect(
      lintFirstmateCard(note({ title: "The auth refactor PR is green" }), context()),
    ).toBeUndefined();
  });

  it("L4: refuses exclamation points and emoji on decision/note copy", () => {
    expect(lintFirstmateCard(note({ body: "Done!" }), context())).toMatch(/exclamation/);
    expect(lintFirstmateCard(note({ title: "Quota 🎉" }), context())).toMatch(/emoji/);
  });

  it("accepts HTML bodies for every card kind", () => {
    expect(lintFirstmateCard(note({ body: "<div>hello</div>" }), context())).toBeUndefined();
    const prototype: EmittedCard = {
      kind: "live-prototype",
      title: "Course preview",
      body: '<div class="fm-row">preview</div>',
      actions: [],
      standalone: true,
    };
    expect(lintFirstmateCard(prototype, context())).toBeUndefined();
  });

  it("L6: refuses re-asking a parked decision by exact card id", () => {
    const parked = new Set([resolveFirstmateCardId("fm-release-choice")]);
    const card = note({
      kind: "decision",
      title: "Choose the release train",
      body: "Ship now or wait for the fix.",
      actions: [{ id: "ship", label: "Ship" }],
      id: "fm-release-choice",
    });
    expect(lintFirstmateCard(card, context({ parkedDecisionIds: () => parked }))).toMatch(
      /parked and returns on its own/,
    );
    // A different id is a different decision.
    expect(
      lintFirstmateCard(
        { ...card, id: "fm-other-choice" },
        context({ parkedDecisionIds: () => parked }),
      ),
    ).toBeUndefined();
  });
});

