import { defineTool, type ToolDefinition } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";

/**
 * The crewmate-facing card surface (decision D-9): a custom Pi tool through
 * which a crewmate emits decision, note, and live-prototype cards. The
 * body-authoring contract lives in docs/card-authoring.md and is summarized
 * in the tool description the model sees.
 *
 * Trap to respect: Pi's `tools` allowlist gates custom tools too - the
 * session must list "emit_card" or the tool is silently disabled.
 */

export const EMIT_CARD_TOOL_NAME = "emit_card";
export const CLOSE_CARD_TOOL_NAME = "close_card";

