import { z } from "zod";

/**
 * The card model (decision D-9): decision, task-result, note, and
 * live-prototype, all with uniform chrome - header + body + action buttons.
 * Phase 2 produces streaming task-result cards; phase 4 completes the four
 * kinds and persistence.
 */

export const cardKindSchema = z.enum(["decision", "task-result", "note", "live-prototype"]);
export type CardKind = z.infer<typeof cardKindSchema>;

export const cardActionSchema = z.object({
  id: z.string(),
  label: z.string(),
  variant: z.enum(["primary", "secondary", "ghost", "danger"]).optional(),
});
export type CardAction = z.infer<typeof cardActionSchema>;

export const cardSchema = z.object({
  id: z.string(),
  taskId: z.string().optional(),
  kind: cardKindSchema,
  /** Higher shows first in the stack. */
  priority: z.number(),
  title: z.string(),
