export function createEmitCardTool(
  onCard: OnCardEmitted,
  lint?: CardLint,
  options: { description?: string } = {},
): ToolDefinition {
  return defineTool({
    name: EMIT_CARD_TOOL_NAME,
    label: "Emit card",
    description: options.description ?? EMIT_CARD_TOOL_DESCRIPTION,
    parameters: Type.Object({
      kind: Type.Union([
        Type.Literal("decision"),
        Type.Literal("note"),
        Type.Literal("live-prototype"),
      ]),
      title: Type.String({ description: "Short sentence-case title" }),
      body: Type.String({
        description: "Semantic HTML fragment for the sandboxed card body",
      }),
      id: Type.Optional(
        Type.String({
          description:
            "Stable kebab-case id namespaced by the emitter (fm-feed-scroll). Reuse when revising the same topic so the open card updates in place.",
        }),
      ),
      actions: Type.Optional(
        Type.Array(
          Type.Object({
            id: Type.String({ description: "Stable action id, kebab-case" }),
            label: Type.String({ description: "Button label, sentence case" }),
          }),
          { description: "Action buttons; the user's choice is reported back" },
        ),
      ),
      task_id: Type.Optional(
        Type.String({
          description:
            "The task this card is about: an answer about existing work, or a decision gating it (required when offering land, merge-pr, or settle actions)",
        }),
      ),
      standalone: Type.Optional(
        Type.Boolean({
          description:
            "For a note about no existing work: true asserts the ask is a one-off with no connection or consequence to any task, so it is filed as its own question",
        }),
      ),
    }),
    execute: async (_toolCallId, params) => {
      if (params.body.length > 65_536) {
        throw new Error("Card body too large (64KB max); emit a smaller card.");
      }
      const id = parseStableCardId(params.id);
      const card: EmittedCard = {
        kind: params.kind,
        title: params.title,
        body: params.body,
        actions: (params.actions ?? []).map((action) => ({ id: action.id, label: action.label })),
        ...(id ? { id } : {}),
        ...(params.task_id?.trim() ? { taskId: params.task_id.trim() } : {}),
        ...(params.standalone ? { standalone: true } : {}),
      };
      const refusal = lint?.(card);
      if (refusal) {
        throw new Error(`Card refused: ${refusal}`);
      }
      const cardId = onCard(card);
      const shown =
        typeof cardId === "string" && cardId
          ? `Card shown: ${params.title} (${cardId})`
          : `Card shown: ${params.title}`;
      return {
        content: [{ type: "text", text: shown }],
        details: {},
      };
    },
  }) as ToolDefinition;
}

