import { type Card, cardSchema } from "@shared/cards";
import type { AppDatabase } from "./db";

/**
 * Persisted cards (decision D-9): unresolved cards survive a restart and
 * reappear in the stack; resolving keeps the chosen action on the row.
 * A task's cards die with the task (decision D-13).
 */

type Row = {
  id: string;
  task_id: string | null;
  kind: string;
  priority: number;
  title: string;
  meta: string;
  body: string;
  actions_json: string;
  status: Card["status"];
  created_at: number;
};

/** Pre-rename rows stored kind "status"; the live enum value is "note". */
function readKind(kind: string): string {
  return kind === "status" ? "note" : kind;
}

function fromRow(row: Row): Card | undefined {
  const parsed = cardSchema.safeParse({
    id: row.id,
    ...(row.task_id ? { taskId: row.task_id } : {}),
    kind: readKind(row.kind),
    priority: row.priority,
    title: row.title,
    meta: row.meta,
    body: row.body,
    actions: JSON.parse(row.actions_json),
    status: row.status,
    createdAt: row.created_at,
  });
  return parsed.success ? parsed.data : undefined;
}

export class CardStore {
  constructor(private readonly db: AppDatabase) {}

  upsert(card: Card): void {
    this.db
      .prepare(
        `INSERT INTO cards (id, task_id, kind, priority, title, meta, body, actions_json, status, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET
           kind = excluded.kind,
           priority = excluded.priority,
           title = excluded.title,
           meta = excluded.meta,
           body = excluded.body,
           actions_json = excluded.actions_json,
           status = excluded.status,
           created_at = excluded.created_at`,
      )
      .run(
        card.id,
        card.taskId ?? null,
        card.kind,
        card.priority,
        card.title,
        card.meta,
        card.body,
        JSON.stringify(card.actions),
        card.status,
        card.createdAt,
      );
  }

  /** Unresolved cards, restored into the stack on boot. */
  listOpen(): Card[] {
    const rows = this.db
      .prepare("SELECT * FROM cards WHERE resolved_at IS NULL ORDER BY created_at")
      .all() as Row[];
    return rows.flatMap((row) => {
      const card = fromRow(row);
      return card ? [card] : [];
    });
  }

  resolve(cardId: string, chosenAction: string): void {
    this.db
      .prepare("UPDATE cards SET resolved_at = ?, chosen_action = ? WHERE id = ?")
      .run(Date.now(), chosenAction, cardId);
  }

  /** One card by id, resolved or not - the park/resurface path reads it. */
  get(cardId: string): Card | undefined {
    const row = this.db.prepare("SELECT * FROM cards WHERE id = ?").get(cardId) as Row | undefined;
    return row ? fromRow(row) : undefined;
  }

  /**
   * A parked decision returning to the stack (R1): clear the resolution so
   * the card is open again and survives the next restart like any other.
   */
  reopen(cardId: string): void {
    this.db
      .prepare("UPDATE cards SET resolved_at = NULL, chosen_action = NULL WHERE id = ?")
      .run(cardId);
  }

  chosenAction(cardId: string): string | undefined {
    const row = this.db.prepare("SELECT chosen_action FROM cards WHERE id = ?").get(cardId) as
      | { chosen_action: string | null }
      | undefined;
    return row?.chosen_action ?? undefined;
  }

  deleteForTask(taskId: string): void {
    this.db.prepare("DELETE FROM cards WHERE task_id = ?").run(taskId);
  }
}

