type TurnImages = Array<{ mimeType: string; data: string }> | undefined;

type FakeSession = FirstmateSession & {
  prompts: string[];
  steers: string[];
  promptImages: TurnImages[];
  steerImages: TurnImages[];
  emitTurnEnd: (text: string, usage?: Record<string, number>) => void;
  /** A provider-failed turn: Pi resolves it, the message carries the error. */
  emitTurnFailed: (errorMessage: string) => void;
  emitDelta: (text: string) => void;
  resolveNextPrompt: () => void;
  rejectNextPrompt: (message: string) => void;
};

function fakeSession(
  model: { provider: string; id: string } = { provider: "fm-mock", id: "mock-1" },
): FakeSession {
  const listeners = new Set<(event: unknown) => void>();
  const prompts: string[] = [];
  const steers: string[] = [];
  const promptImages: TurnImages[] = [];
  const steerImages: TurnImages[] = [];
  let streaming = false;
  let resolvePrompt: (() => void) | undefined;
  let rejectPrompt: ((error: Error) => void) | undefined;
  return {
    sessionId: "fm-session",
    sessionFile: "/tmp/fm/sessions/session.jsonl",
    isStreaming: () => streaming,
    modelRef: () => model,
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    prompt: (text: string, images?: TurnImages) => {
      prompts.push(text);
      promptImages.push(images);
      streaming = true;
      return new Promise<void>((resolve, reject) => {
        resolvePrompt = () => {
          streaming = false;
          resolve();
        };
        rejectPrompt = (error) => {
          streaming = false;
          reject(error);
        };
      });
    },
    steer: async (text: string, images?: TurnImages) => {
      steers.push(text);
      steerImages.push(images);
    },
    abort: async () => {},
    dispose: vi.fn(),
    prompts,
    steers,
    promptImages,
    steerImages,
    emitTurnEnd: (text, usage) => {
      for (const listener of listeners) {
        listener({
          type: "turn_end",
          message: {
            role: "assistant",
            content: [{ type: "text", text }],
            ...(usage ? { usage } : {}),
          },
        });
      }
    },
    emitTurnFailed: (errorMessage) => {
      for (const listener of listeners) {
        listener({
          type: "turn_end",
          message: {
            role: "assistant",
            content: [],
            stopReason: "error",
            errorMessage,
          },
        });
      }
    },
    emitDelta: (text: string) => {
      for (const listener of listeners) {
        listener({
          type: "message_update",
          assistantMessageEvent: { type: "text_delta", delta: text },
        });
      }
    },
    resolveNextPrompt: () => resolvePrompt?.(),
    rejectNextPrompt: (message) => rejectPrompt?.(new Error(message)),
  };
}

function setup(
  options: {
    session?: FakeSession;
    failCreate?: string;
    availableModels?: () => { provider: string; id: string }[];
    consultant?: {
      consult(input: { question: string; repoId?: string; quote?: string }): Promise<string>;
    };
