    modelRuntime: {} as ModelRuntime,
    availableModels: options.availableModels ?? (() => [{ provider: "fm-mock", id: "mock-1" }]),
    quotaModels: () => undefined,
    quotaLine: () => "codex 62% weekly on_pace",
