// L6: the parked-decision re-ask refusal, exact-id keyed.
if (card.kind === "decision" && card.id) {
  const resolved = context.resolveCardId(card.id);
  if (context.parkedDecisionIds().has(resolved)) {
    return "that decision is parked and returns on its own; recall_decision brings it back now.";
  }
}

// Cross-turn duplicate-decision gate: an open decision on the task is
// already the captain's control surface, whichever turn raised it. A new
// decision would stack a second one. Revising that same id in place is
// the allowed update. A crew note is not a decision, so the missing
// merge-control path can still add one.
if (card.kind === "decision" && card.taskId && context.openCardsForTask) {
  const resolved = card.id ? context.resolveCardId(card.id) : undefined;
  const existing = context
    .openCardsForTask(card.taskId)
    .find((open) => open.kind === "decision" && open.id !== resolved);
  if (existing) {
    return `task ${card.taskId} already has an open card (${existing.id}); do not emit a second decision. Reuse that emit_card id to revise it in place, or close_card it first.`;
  }
}

