  it("refuses a new decision when the task already has an open decision", () => {
    const card = note({
      kind: "decision",
      title: "Finish the auth refactor",
      body: "Ready. https://github.com/x/y/pull/23",
      actions: [{ id: "merge-pr", label: "Merge PR" }],
      taskId: "ab12cd34",
    });
    const ctx = context({
      taskDelivery: () => "direct-pr",
      freshGreenCi: () => true,
      openCardsForTask: (taskId) =>
        taskId === "ab12cd34"
          ? [{ id: "card-fm-settle", kind: "decision" }]
          : [],
    });
    expect(lintFirstmateCard(card, ctx)).toBe(
      "task ab12cd34 already has an open card (card-fm-settle); do not emit a second decision. Reuse that emit_card id to revise it in place, or close_card it first.",
    );
    // Revising the same open card in place is the allowed update.
    expect(lintFirstmateCard({ ...card, id: "settle" }, ctx)).toBeUndefined();
    expect(lintFirstmateCard({ ...card, id: "card-fm-settle" }, ctx)).toBeUndefined();
    // A crew note is not a second decision; the merge control can still land.
    expect(
      lintFirstmateCard(
        card,
        context({
          taskDelivery: () => "direct-pr",
          freshGreenCi: () => true,
          openCardsForTask: () => [{ id: "card-ab12cd34-1", kind: "note" }],
        }),
      ),
    ).toBeUndefined();
    // A note about the same task does not stack a second decision.
    expect(
      lintFirstmateCard(
        note({ taskId: "ab12cd34", standalone: undefined }),
        context({
          openCardsForTask: () => [{ id: "card-fm-settle", kind: "decision" }],
        }),
      ),
    ).toBeUndefined();
    // No stack to check against trusts the emit.
    expect(
      lintFirstmateCard(card, context({ taskDelivery: () => "direct-pr", freshGreenCi: () => true })),
    ).toBeUndefined();
  });
});

