it("refuses a new decision when an earlier turn already left one open", async () => {
  const { agent, specs, supervisor } = setup({
    seedTasks: [{ id: "t90", title: "Ship the fix", status: "idle" }],
    seedCards: [
      {
        id: "card-fm-settle",
        taskId: "t90",
        kind: "decision",
        priority: 50,
        title: "The fix is ready to settle",
        meta: "firstmate",
        body: "The work is done; settling it is the captain's call.",
        actions: [
          { id: "keep", label: "Keep" },
          { id: "discard", label: "Discard" },
        ],
        status: "ready",
        createdAt: Date.now(),
      },
    ],
  });
  await agent.converse("an unrelated later wake");
  const tools = (specs[0]?.customTools ?? []) as unknown as Array<{
    name: string;
    execute: (
      id: string,
      params: Record<string, unknown>,
    ) => Promise<{ content: { type: string; text?: string }[] }>;
  }>;
  const emit = tools.find((tool) => tool.name === "emit_card");
  const duplicate = {
    kind: "decision",
    title: "The fix is ready to settle",
    body: "Checking CI again stacked a second settle card.",
    actions: [
      { id: "keep", label: "Keep" },
      { id: "discard", label: "Discard" },
    ],
    task_id: "t90",
  };
  await expect(emit?.execute("c1", duplicate)).rejects.toThrow(
    /already has an open card \(card-fm-settle\)/,
  );
  expect(supervisor.cardsSnapshot()).toHaveLength(1);
  const revised = await emit?.execute("c2", { ...duplicate, id: "settle" });
  expect(revised?.content[0]?.text).toContain("card-fm-settle");
  expect(supervisor.cardsSnapshot()).toHaveLength(1);
});

it("refuses a new decision when a crewmate decision is still open from an earlier turn", async () => {
  const { agent, specs, supervisor } = setup({
    seedTasks: [{ id: "t91", title: "Ship the fix", status: "idle" }],
    seedCards: [
      {
        id: "card-t91-1",
        taskId: "t91",
        kind: "decision",
        priority: 30,
        title: "The fix is ready to settle",
        meta: "crewmate 9",
        body: "The crewmate already offered keep or discard.",
        actions: [
          { id: "keep", label: "Keep" },
          { id: "discard", label: "Discard" },
        ],
        status: "ready",
        createdAt: Date.now(),
      },
    ],
  });
  await agent.converse("an unrelated later wake");
  const tools = (specs[0]?.customTools ?? []) as unknown as Array<{
    name: string;
    execute: (
      id: string,
      params: Record<string, unknown>,
    ) => Promise<{ content: { type: string; text?: string }[] }>;
  }>;
  const emit = tools.find((tool) => tool.name === "emit_card");
  await expect(
    emit?.execute("c1", {
      kind: "decision",
      title: "The fix is ready to settle",
      body: "A later wake must not stack another settle card.",
      actions: [
        { id: "keep", label: "Keep" },
        { id: "discard", label: "Discard" },
      ],
      task_id: "t91",
    }),
  ).rejects.toThrow(/already has an open card \(card-t91-1\)/);
  expect(supervisor.cardsSnapshot()).toHaveLength(1);
});

